<?php $base='/research/'.$r['slug'];$events=array_reverse(wf_ledger($r['id'],$private)); ?>
<div class="workflow-heading"><a class="back" href="<?=e($private?'/admin/research/'.$r['id']:$base.'/work')?>">← <?=e($private?'Administration':'Research workflow')?></a><h1><?=e($private?'Private audit ledger':'Catch up on the research')?></h1><p><span class="status"><?=e($r['status'])?></span> · All timestamps are UTC</p><div class="actions primary-actions"><?php if(!$private): ?><a class="button" href="<?=e($base)?>/work">See next available work</a><a class="button secondary" href="<?=e($base)?>/package.json">Full context package</a><?php endif ?></div></div>
<p class="fine">Append-only updates: corrections add a new event. Public identity and AI provenance are self-reported. Private operational events are visible only in administration.</p>
<?php foreach($events as $event): $meta=json_decode($event['metadata'],true); ?>
<article class="ledger-entry" id="event-<?=e($event['id'])?>"><div class="row-top"><time datetime="<?=e(str_replace(' ','T',$event['created_at']).'Z')?>"><?=e($event['created_at'])?> UTC</time><span class="status"><?=e($event['new_state']?:$event['action'])?></span></div><h2><?=e($event['action'])?></h2><p><?=e($event['reason'])?></p><p class="fine"><strong>Who:</strong> <?=e($event['actor_name'])?> (<?=e($event['actor_type'])?>) · <strong>Where:</strong> <?=e($event['entity_type'])?> <?=e($event['entity_id'])?><br><strong>Change:</strong> <?=e($event['old_state']?:'—')?> → <?=e($event['new_state']?:'No state change')?></p>
<?php if($event['entity_type']==='submission' && one("SELECT id FROM workflow_submissions WHERE id=? AND visibility='public'",[$event['entity_id']])): ?><a href="<?=e($base)?>/results/<?=e($event['entity_id'])?>">Full result & evidence</a><?php elseif($event['entity_type']==='task'): ?><a href="<?=e($base)?>/tasks/<?=e($event['entity_id'])?>">Task details</a><?php endif ?>
<?php if($event['next_action']): ?><p><strong>Next:</strong> <?=e($event['next_action'])?></p><?php endif ?><?php if($meta): ?><details><summary>How / provenance</summary><pre><?=e(json_encode($meta,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre><?php if(isset($meta['context_id'])): ?><a href="<?=e($private?'/admin/research/'.$r['id']:$base)?>/packages/<?=e($meta['context_id'])?>">Exact input context package</a><?php endif ?></details><?php endif ?></article>
<?php endforeach ?>
<?php if($private): ?><h2>Rejected attempts (private)</h2><?php foreach(all('SELECT * FROM workflow_attempts WHERE research_id=? ORDER BY created_at,id',[$r['id']]) as $attempt): ?><details><summary><?=e($attempt['created_at'])?> UTC · <?=e($attempt['reason'])?></summary><pre><?=e($attempt['payload'])?></pre></details><?php endforeach ?><?php endif ?>
